"""Zustand pro Szenario + alle PM-Aktionen (Owner: Lead).

Warum ein zentraler Store: Jede Änderung an einer Anforderung (PM-Entscheidung,
Gewichte, Bearbeitung) läuft durch GENAU diese Klasse und erzeugt ein Audit-Ereignis.
So kann keine Änderung am Prüfpfad vorbeigehen.

Datenquelle: data/processed/<szenario>.json (von pipeline.py erzeugt). Fehlt sie,
nehmen wir src/shared/beispiele/bundle_<szenario>.json, damit Frontend und Tests
ohne OpenAI-Key und ohne BMW-Rohdaten laufen.
"""

from __future__ import annotations

import json
import os
from pathlib import Path

from pydantic import ValidationError

from core.audit import AuditLog
from core.models import Actor, ActorType, Evidence, Requirement, Scenario, Signal, Status
from core.replay import replay
from requirements_engine import scoring

ROOT = Path(__file__).resolve().parents[3]
PROCESSED_DIR = ROOT / "data" / "processed"
EXAMPLES_DIR = ROOT / "src" / "shared" / "beispiele"
SYSTEM = Actor(type=ActorType.SYSTEM, name="pipeline")


class ScenarioState:
    def __init__(self, bundle: dict):
        self.scenario = Scenario(**bundle["scenario"])
        # Warnungen sind reiner Anzeigetext: aus config/ nachladen, damit eine Textkorrektur
        # (z. B. Übersetzung) keinen teuren Pipeline-Lauf braucht. Zahlen bleiben im Bundle.
        config = ROOT / "config" / "scenarios" / f"{self.scenario.id}.json"
        if config.exists():
            warnings = json.loads(config.read_text(encoding="utf-8")).get("warnings")
            if isinstance(warnings, list):
                self.scenario.warnings = warnings
        self.funnel: dict = bundle.get("funnel", {})
        self.evidence = {e["id"]: Evidence(**e) for e in bundle["evidence"]}
        self.signals = {s["id"]: Signal(**s) for s in bundle["signals"]}
        self.requirements = {r["id"]: Requirement(**r) for r in bundle["requirements"]}
        self.discarded: list[dict] = bundle.get("discarded", [])  # Beispiel-Bundles haben das Feld nicht
        self.weights = scoring.normalize_weights(bundle.get("weights", {}))
        # Welle 2: Kontext (Absatz, unbekannte Themen) und Chancen-Karte, fertig aus der Pipeline
        self.context: dict = bundle.get("context", {})
        self.opportunities: list[dict] = bundle.get("opportunities", [])


class Store:
    def __init__(self, audit: AuditLog):
        self.audit = audit
        self.states: dict[str, ScenarioState] = {}

    # ─── Laden ──────────────────────────────────────────────────────────────
    def load_all(self) -> None:
        """Echte Pipeline-Ergebnisse haben Vorrang; Beispiele nur für Szenarien ohne Ergebnis."""
        processed_dir = Path(os.getenv("PROCESSED_DIR", PROCESSED_DIR))
        sources = {p.stem.removeprefix("bundle_"): p for p in sorted(EXAMPLES_DIR.glob("bundle_*.json"))}
        sources |= {p.stem: p for p in sorted(processed_dir.glob("*.json"))}
        for path in sources.values():
            state = ScenarioState(json.loads(path.read_text(encoding="utf-8")))
            self.states[state.scenario.id] = state
            history = self.audit.events(scenario_id=state.scenario.id)
            if history:
                replay(state, history)  # PM-Entscheidungen überleben den Neustart (L19)
            self._rescore(state)  # Score immer aus der Formel (mit evtl. wiederhergestellten Gewichten)
            if not history:
                self._log_initial_proposals(state, path.name)

    def _log_initial_proposals(self, state: ScenarioState, source: str) -> None:
        """Erste Einträge im Prüfpfad: woher die Vorschläge stammen."""
        sid = state.scenario.id
        self.audit.append("PIPELINE_LOADED", sid, SYSTEM, f"Ergebnisse geladen aus {source}", {"funnel": state.funnel})
        for req in sorted(state.requirements.values(), key=lambda r: r.rank):
            self.audit.append(
                "REQUIREMENT_PROPOSED", sid, Actor(type=ActorType.AI, name="pipeline"),
                req.rationale, {"score": req.score, "evidence_level": req.evidence_level.value,
                                "signal_ids": req.signal_ids}, requirement_id=req.id,
            )
        for item in state.discarded:  # Begründung = Scope-Grund der KI; ohne requirement_id, es gibt keine Anforderung
            self.audit.append(
                "REQUIREMENT_DISCARDED", sid, Actor(type=ActorType.AI, name="scope-waechter"),
                item.get("reason") or "Außerhalb des Scopes",
                {"title": item["title"], "signal_ids": item["signal_ids"]},
            )

    def get(self, scenario_id: str) -> ScenarioState:
        if scenario_id not in self.states:
            raise KeyError(f"Unbekanntes Szenario: {scenario_id}")
        return self.states[scenario_id]

    def find_requirement(self, req_id: str) -> tuple[ScenarioState, Requirement]:
        for state in self.states.values():
            if req_id in state.requirements:
                return state, state.requirements[req_id]
        raise KeyError(f"Unbekannte Anforderung: {req_id}")

    # ─── PM-Aktionen (jede erzeugt ein Audit-Ereignis) ─────────────────────
    def decide(
        self, req_id: str, action: str, actor: Actor, rationale: str, changes: dict | None = None
    ) -> Requirement:
        state, req = self.find_requirement(req_id)
        before = req.model_dump(mode="json")
        if action == "approve":
            req.status = Status.APPROVED
        elif action == "reject":
            req.status = Status.REJECTED
        elif action == "edit":
            allowed = {"title", "description", "acceptance_criterion", "effort", "assumptions", "uncertainties"}
            bad = set(changes or {}) - allowed
            if bad or not changes:
                raise ValueError(f"Bearbeitbar sind nur: {sorted(allowed)}")
            # model_validate statt model_copy: prüft die neuen Werte (z. B. effort nur S/M/L),
            # sonst landet ein ungültiger Zustand im Store und im Prüfpfad.
            try:
                req = Requirement.model_validate({**before, **changes, "version": req.version + 1})
            except ValidationError as err:
                raise ValueError(f"Ungültige Änderung: {err.errors()[0]['msg']}") from err
            state.requirements[req_id] = req
            if "effort" in changes:
                self._rescore(state)
        elif action == "challenge":
            req.status = Status.CHALLENGED
        else:
            raise ValueError(f"Unbekannte Aktion: {action}")
        after = req.model_dump(mode="json")
        diff = {k: {"before": before[k], "after": after[k]} for k in after if before.get(k) != after[k]}
        self.audit.append(f"PM_{action.upper()}", state.scenario.id, actor, rationale, diff, requirement_id=req_id)
        return state.requirements[req_id]

    def set_weights(
        self, scenario_id: str, weights: dict[str, float], actor: Actor, rationale: str
    ) -> list[Requirement]:
        state = self.get(scenario_id)
        before = {r.id: (r.rank, r.score) for r in state.requirements.values()}
        old_weights = state.weights
        state.weights = scoring.normalize_weights(weights)
        self._rescore(state)
        changes = {r.id: {"before": before[r.id], "after": (r.rank, r.score)} for r in state.requirements.values()
                   if before[r.id] != (r.rank, r.score)}
        self.audit.append("WEIGHTS_CHANGED", scenario_id, actor, rationale,
                          {"weights": {"before": old_weights, "after": state.weights}, "rank_changes": changes})
        return self.ranked(scenario_id)

    def _rescore(self, state: ScenarioState) -> None:
        """Neu rechnen mit den gespeicherten Faktorwerten, dann neu ranken."""
        for req in state.requirements.values():
            values = {k: f.value for k, f in req.score_breakdown.items()}
            values["effort_inverse"] = scoring.effort_factor(req.effort)
            texts = {k: f.explanation for k, f in req.score_breakdown.items()}
            req.score, req.score_breakdown = scoring.score(values, texts, req.evidence_level, state.weights)
        for rank, req in enumerate(sorted(state.requirements.values(), key=lambda r: -r.score), start=1):
            req.rank = rank

    def ranked(self, scenario_id: str) -> list[Requirement]:
        return sorted(self.get(scenario_id).requirements.values(), key=lambda r: r.rank)

"""Endpunkte für fertige Ansichten (Owner: Lead). Vertrag für Menschen: src/shared/API.md.

Dünn wie routes.py: Eingaben prüfen, Zustand holen, eine reine Funktion aus core/ aufrufen.
Keine dieser Routen schreibt etwas; nur PUT /weights und POST /decision (routes.py) ändern Zustand.
"""

from __future__ import annotations

from fastapi import APIRouter, HTTPException, Query, Request
from pydantic import BaseModel

from core import insights, portfolio, views
from core.product_context import product_context
from core.store import ROOT, Store

router = APIRouter(prefix="/api")

EVENT_SENTENCE = {
    "PIPELINE_LOADED": "Pipeline-Ergebnis geladen", "REQUIREMENT_PROPOSED": "KI schlägt Anforderung vor",
    "REQUIREMENT_DISCARDED": "KI verwirft Entwurf (außerhalb des Scopes)", "PM_APPROVE": "PM gibt frei",
    "PM_REJECT": "PM lehnt ab", "PM_EDIT": "PM bearbeitet", "PM_CHALLENGE": "PM stellt Gegenfrage",
    "AI_RESPONDED": "KI antwortet mit Belegen", "WEIGHTS_CHANGED": "PM ändert Gewichte",
    "AI_LENS_SUGGESTED": "KI schlägt Linse (Gewichte + Filter) vor",
}


class WhatIfIn(BaseModel):
    weights: dict[str, float]


def _store(request: Request) -> Store:
    return request.app.state.store


def _state(request: Request, scenario_id: str):
    try:
        return _store(request).get(scenario_id)
    except KeyError as err:
        raise HTTPException(status_code=404, detail=str(err.args[0])) from err


@router.get("/scenarios")
def list_scenarios(request: Request) -> list[dict]:
    """Szenario-Wähler: Szenario + Datenabdeckung + Badge (reich / dünn / Kaltstart) + Kopfzahlen."""
    return [views.scenario_card(s) for s in _store(request).states.values()]


@router.get("/scenarios/{scenario_id}/overview")
def overview(scenario_id: str, request: Request) -> dict:
    return views.overview(_state(request, scenario_id))


@router.get("/scenarios/{scenario_id}/product-context")
def current_product_context(scenario_id: str, request: Request) -> dict:
    return product_context(_state(request, scenario_id), ROOT)


@router.get("/requirements/{req_id}/explain")
def explain(req_id: str, request: Request) -> dict:
    store = _store(request)
    try:
        state, req = store.find_requirement(req_id)
    except KeyError as err:
        raise HTTPException(status_code=404, detail=str(err.args[0])) from err
    return views.explain(state, req, store.audit.events(requirement_id=req_id))


@router.post("/scenarios/{scenario_id}/whatif")
def whatif(scenario_id: str, body: WhatIfIn, request: Request) -> list[dict]:
    """Live-Vorschau für den Gewichte-Regler. Speichert nichts und schreibt kein Audit."""
    try:
        return views.whatif(_state(request, scenario_id), body.weights)
    except ValueError as err:
        raise HTTPException(status_code=422, detail=str(err)) from err


@router.get("/portfolio")
def portfolio_matrix(request: Request) -> dict:
    return portfolio.portfolio(_store(request).states)


@router.get("/compare")
def compare(request: Request, a: str = Query(examples=["G60-US"]), b: str = Query(examples=["G60-EU"])) -> dict:
    return portfolio.compare(_state(request, a), _state(request, b))


@router.get("/scenarios/{scenario_id}/opportunities")
def opportunities(scenario_id: str, request: Request) -> dict:
    return insights.opportunities(_state(request, scenario_id))


@router.get("/scenarios/{scenario_id}/trends")
def trends(scenario_id: str, request: Request) -> dict:
    return insights.trends(_state(request, scenario_id))


@router.get("/scenarios/{scenario_id}/gaps")
def gaps(scenario_id: str, request: Request) -> dict:
    return insights.gaps(_state(request, scenario_id))


@router.get("/scenarios/{scenario_id}/evidence")
def evidence(scenario_id: str, request: Request, signal: str | None = None, segment: str | None = None,
             q: str | None = None, page: int = Query(1, ge=1), size: int = Query(20, ge=1, le=100)) -> dict:
    return insights.evidence_page(_state(request, scenario_id), signal, segment, q, page, size)


@router.get("/audit/timeline")
def audit_timeline(request: Request, scenario_id: str | None = None, requirement_id: str | None = None) -> list[dict]:
    """Prüfpfad als lesbare Zeitleiste: ein Satz pro Ereignis, wer (KI/Mensch/System), warum."""
    return [{"seq": e.seq, "ts": e.ts, "actor": e.actor, "requirement_id": e.requirement_id,
             "event_type": e.event_type, "sentence": EVENT_SENTENCE.get(e.event_type, e.event_type),
             "rationale": e.rationale}
            for e in _store(request).audit.events(scenario_id, requirement_id)]

"""Vergleich über Szenarien: Portfolio-Matrix und Markt-Vergleich (Owner: Lead).

Warum: BMW will "scale across vehicle lines and markets". Die Matrix zeigt, ob ein Thema
eine Plattform-Entscheidung ist (überall oben) oder nur ein Modell bzw. einen Markt betrifft.
Die Klassen sind Regeln in Python, damit der PM sie nachrechnen kann.
"""

from __future__ import annotations

from core.models import Category, Requirement
from core.views import LEVEL_LABEL, coverage

TOP_N = 5  # "oben" heißt: mindestens eine Anforderung des Themas unter den ersten 5


def _best_per_category(requirements) -> dict[str, Requirement]:
    best: dict[str, Requirement] = {}
    for req in sorted(requirements, key=lambda r: r.rank):
        best.setdefault(req.category.value, req)
    return best


def _cell(req: Requirement | None) -> dict | None:
    if req is None:
        return None
    return {"requirement_id": req.id, "title": req.title, "rank": req.rank, "score": req.score,
            "evidence_level": req.evidence_level, "level_label": LEVEL_LABEL[req.evidence_level.value]}


def classify(top_scenarios: list, all_scenarios: list) -> str:
    """Regel: in ≥ 2/3 aller Szenarien oben = plattformweit; nur ein Modell = modellspezifisch;
    nur ein Markt = marktspezifisch; sonst gemischt. Keine Nennung oben = nicht oben."""
    if not top_scenarios:
        return "nicht oben"
    if len(top_scenarios) >= max(2, round(len(all_scenarios) * 2 / 3)):
        return "plattformweit"
    if len(top_scenarios) == 1:
        return "einzeln"
    if len({s.derivative for s in top_scenarios}) == 1:
        return "modellspezifisch"
    if len({s.market for s in top_scenarios}) == 1:
        return "marktspezifisch"
    return "gemischt"


def portfolio(states: dict) -> dict:
    """Matrix Kategorie × Szenario mit bestem Rang und Evidenzstufe je Zelle."""
    scenario_ids = sorted(states)
    best = {sid: _best_per_category(states[sid].requirements.values()) for sid in scenario_ids}
    scenarios = [states[sid].scenario for sid in scenario_ids]
    rows = []
    for cat in Category:
        cells = {sid: _cell(best[sid].get(cat.value)) for sid in scenario_ids}
        top = [states[sid].scenario for sid in scenario_ids if cells[sid] and cells[sid]["rank"] <= TOP_N]
        rows.append({"category": cat.value, "cells": cells, "class": classify(top, scenarios),
                     "top_in": [s.id for s in top]})
    rows.sort(key=lambda r: (-len(r["top_in"]), r["category"]))
    return {
        "scenarios": [{"id": s.id, "model_name": s.model_name, "market": s.market,
                       "data_coverage": coverage(states[s.id]).model_dump()} for s in scenarios],
        "rows": rows, "top_n": TOP_N,
        "rule": "plattformweit = in mind. 2/3 der Szenarien unter den Top 5; modell-/marktspezifisch = nur ein "
                "Modell bzw. ein Markt; einzeln = nur ein Szenario.",
    }


def compare(state_a, state_b) -> dict:
    """Gleiche Themen nebeneinander: Rang und Unzufriedenheit (Studie) in Szenario A und B."""
    best_a = _best_per_category(state_a.requirements.values())
    best_b = _best_per_category(state_b.requirements.values())
    opp_a = {o.get("category"): o.get("dissatisfaction") for o in state_a.opportunities}
    opp_b = {o.get("category"): o.get("dissatisfaction") for o in state_b.opportunities}
    rows = []
    for cat in Category:
        a, b = best_a.get(cat.value), best_b.get(cat.value)
        if not a and not b:
            continue
        rank_diff = (a.rank - b.rank) if a and b else None
        rows.append({"category": cat.value, "a": _cell(a), "b": _cell(b), "rank_diff": rank_diff,
                     "dissatisfaction_a": opp_a.get(cat.value), "dissatisfaction_b": opp_b.get(cat.value),
                     "sentence": _compare_sentence(cat.value, a, b, state_a.scenario.id, state_b.scenario.id)})
    rows.sort(key=lambda r: min(x["rank"] for x in (r["a"], r["b"]) if x))
    return {"a": state_a.scenario.id, "b": state_b.scenario.id, "rows": rows}


def _compare_sentence(category: str, a, b, id_a: str, id_b: str) -> str:
    if a and not b:
        return f"{category}: nur in {id_a} eine Anforderung (Rang {a.rank})."
    if b and not a:
        return f"{category}: nur in {id_b} eine Anforderung (Rang {b.rank})."
    if a.rank == b.rank:
        return f"{category}: in beiden Märkten Rang {a.rank}."
    higher, lower = (id_a, id_b) if a.rank < b.rank else (id_b, id_a)
    return f"{category}: in {higher} wichtiger (Rang {min(a.rank, b.rank)} vs. {max(a.rank, b.rank)} in {lower})."

