2	
3	import { useEffect, useState } from "react";
4	import Link from "next/link";
5	import { usePathname, useRouter, useSearchParams } from "next/navigation";
6	import { getScenarios, type Scenario } from "@/src/lib/api";
7	import { Logo } from "@/src/components/ui/Logo";
8	import { MStripe } from "@/src/components/ui/MStripe";
9	import { Icon } from "@/src/components/ui/Icon";
10	import { DEFAULT_SCENARIO_ID, scenarioLabel } from "./scenarioLabel";
11	
12	// Model selection, decisions, comparison and history are the primary PM destinations.
13	const NAV = [
14	  { href: "/models", label: "Models" },
15	  { href: "/cockpit", label: "Cockpit" },
16	  { href: "/portfolio", label: "Compare" },
17	  { href: "/audit", label: "Audit trail" },
18	];
19	
20	// Seiten, die ein Szenario in ?scenario= verstehen. Das Szenario-Menü bleibt auf der Seite, statt ins Cockpit zu springen.
21	const SCENARIO_PAGES = ["/cockpit", "/insights", "/evidence", "/audit"];
22	
23	// Nur das Cockpit braucht ein Szenario. Der Audit-Trail startet bewusst mit "All scenarios",
24	// damit PMs zuerst die ganze Entscheidungshistorie sehen und dann selbst filtern.
25	function navHref(href: string, scenarioId: string) {
26	  return href === "/cockpit" ? `${href}?scenario=${scenarioId}` : href;
27	}
28	
29	export function SiteHeader() {
30	  const pathname = usePathname();
31	  const router = useRouter();
32	  const params = useSearchParams();
33	  const [scenarios, setScenarios] = useState<Scenario[]>([]);
34	  // Wir merken die Route, bei der das Menü geöffnet wurde: Routenwechsel schließt es automatisch,
35	  // ohne setState im Effect.
36	  const [mobilePath, setMobilePath] = useState<string | null>(null);
37	  const mobileOpen = mobilePath === pathname;
38	  const setMobileOpen = (open: boolean | ((v: boolean) => boolean)) =>
39	    setMobilePath((cur) => ((typeof open === "function" ? open(cur === pathname) : open) ? pathname : null));
40	  const [scrolled, setScrolled] = useState(false);
41	
42	  const isHome = pathname === "/";
43	  // Auf der Startseite liegt der Header transparent über dem schwarzen Hero.
44	  const light = isHome && !scrolled && !mobileOpen;
45	  // Das Szenario steckt in der URL (?scenario=), so teilen Header, Cockpit und Menü denselben Zustand.
46	  const scenarioId = params.get("scenario") ?? DEFAULT_SCENARIO_ID;
47	
48	  useEffect(() => {
49	    getScenarios().then(setScenarios).catch(() => setScenarios([]));
50	  }, []);
51	
52	  useEffect(() => {
53	    const onScroll = () => setScrolled(window.scrollY > 40);
