for i in $(seq 1 120); do grep -q "Ready" "$TEMP/claude_prod.log" 2>/dev/null && break; sleep 2; done; cd "$TEMP"; cat > pwcheck.cjs <<'EOF'
const { chromium } = require(process.argv[2]);
(async () => {
  const b = await chromium.launch(); const p = await b.newPage({ viewport: { width: 1400, height: 900 } });
  const errs = []; p.on('pageerror', e => errs.push(e.message)); p.on('console', m => m.type()==='error' && errs.push(m.text()));
  await p.goto('http://localhost:3012/benchmarks'); await p.getByText('Where does the model stand?').waitFor();
  await p.getByText('G70-US').first().waitFor();
  console.log('Fehler:', errs.length, errs.slice(0,2)); await b.close();
})();
EOF
PW=$(dirname $(find ~/AppData/Local/npm-cache/_npx -path '*playwright@*' -prune -o -name package.json -path '*node_modules/playwright/package.json' -print 2>/dev/null | xargs grep -l '"version": "1.62.0"' | head -1)); node pwcheck.cjs "$PW"

